import type { Q } from "../types";

export const consultingPart1: Q[] = [
  { t: "What MECE means and why it matters", p: "An interviewer asks you to explain what MECE means and why consultants insist on it when structuring a problem. Explain it and give a short example of a structure that fails the test.", d: 1, tp: "case-structuring", i: "MECE means mutually exclusive and collectively exhaustive: the branches of a structure do not overlap (so nothing is double counted or argued twice) and together they cover the whole problem (so nothing important is missed). It matters because overlap wastes analysis and muddles ownership, while gaps mean the real driver may sit in an unexamined branch. Test it by asking whether any item could belong in two buckets and whether anything in the problem has no home. Example failure: splitting a store's customers into 'young', 'online' and 'high spenders' overlaps (a young online high spender fits all three) and is not exhaustive. A MECE alternative splits by channel (store versus online) and then by new versus existing customers. Equations such as profit = revenue - cost and process steps from start to finish are natural MECE structures, but the cut must also be useful, meaning it isolates where the answer likely lies.", c: ["Mutually exclusive means no overlap between branches", "Collectively exhaustive means nothing relevant is missed", "Test by checking double fits and orphan items", "Structure must also be decision-useful, not just logically clean"], k: ["MECE prevents both double counting and blind spots", "Use natural MECE cuts such as equations, processes and segments, and then prune"], m: ["Thinking a long list of ideas is MECE if it feels comprehensive", "Treating MECE as only a formatting exercise rather than a rigour check"] },
  { t: "Hypothesis-driven versus exhaustive analysis", p: "Why do consultants work hypothesis-first rather than collecting all the data and seeing what it says? Describe how you would apply this in the first ten minutes of a case and what you do if the hypothesis is wrong.", d: 1, tp: "case-structuring", i: "A hypothesis-driven approach states an early, falsifiable answer (for example 'margins fell mainly because input costs rose faster than we could reprice') and then designs the fewest analyses that could prove or disprove it. It is faster than boil-the-ocean data collection because time is short and data is unlimited, and it keeps the team focused on what would change the decision. In the first minutes: absorb the objective, form a provisional hypothesis from the facts and industry knowledge, build a structure that tests it and its main alternatives, and ask for the data that discriminates between them. If the data refutes it, say so openly, state what you learned, and pivot to the next most likely branch; being wrong quickly is the point, as every refuted hypothesis narrows the problem. The danger is confirmation bias, so actively seek disconfirming evidence and keep alternative hypotheses alive until evidence separates them.", c: ["Hypothesis is an early falsifiable answer", "Analyses are designed to prove or disprove it", "Faster and more focused than exhaustive data gathering", "Pivot openly when evidence refutes the hypothesis"], k: ["Seek disconfirming evidence to avoid confirmation bias", "Each refuted hypothesis still narrows the problem"], m: ["Holding on to the hypothesis after the data contradicts it", "Believing a hypothesis means guessing without logic"] },
  { t: "Clarifying questions at the start of a case", p: "You have just heard a case prompt: a regional furniture manufacturer wants to know whether to launch an online direct-to-consumer channel. What clarifying questions do you ask before structuring, and which would you avoid?", d: 1, tp: "case-structuring", i: "Good clarifying questions pin down objective, scope and constraints without fishing for the answer. Objective: what does success look like (profit, growth, share) and over what time horizon? Scope: which products and geographies, and does the client currently sell only through retailers? Context: who are the main customers and what is the client's position (size, brand, margins)? Constraints: investment budget, logistics capability, and whether retailer relationships limit options. Definitions: what exactly does 'launch' mean, a pilot or full roll-out? Ask two or three focused questions, repeat back your understanding, then request a minute to structure. Avoid broad fishing such as 'what are the problems?', questions already answered in the prompt, or asking for data you could reason about yourself. The goal is to show you understand the decision, can define success, and are not wasting the interviewer's time, so cluster questions by theme rather than firing them one by one.", c: ["Clarify objective and success metric", "Clarify scope and what the decision exactly is", "Ask about constraints and client context", "Summarise understanding before structuring"], k: ["Questions should change how you structure the case", "Few focused questions beat a long fishing list"], m: ["Asking questions the prompt already answered", "Skipping clarification and structuring the wrong problem"] },
  { t: "Prioritising branches in a structure", p: "You have built a four-branch structure for a case about a falling-profit regional supermarket group. You cannot analyse everything. How do you decide which branch to explore first and how do you communicate that choice?", d: 1, tp: "case-structuring", i: "Prioritise using a combination of likelihood and impact against effort. Likelihood comes from facts given and industry priors (if revenue is flat and costs are stated to be rising, the cost branch is a stronger candidate). Impact is how much of the problem the branch could explain, and effort is how quickly data can settle it. Start with the branch that is both probable and quick to confirm or eliminate, or that would eliminate the most uncertainty if ruled out. Communicate it explicitly: say which branch you want to start with and why in one sentence, state what you expect to find, and say what result would make you move to the next branch. Also say what you are deliberately parking, so the interviewer sees it is a choice rather than an omission. Revisit the priority as data arrives, since a good case is iterative.", c: ["Rank by likelihood, impact and effort", "Use given facts and industry priors", "State the choice and reasoning aloud", "Say what is parked and what would change the order"], k: ["Pick branches that eliminate the most uncertainty quickly", "Prioritisation is revisited as evidence arrives"], m: ["Working through branches in the order they were written", "Prioritising silently without explaining why"] },
  { t: "Delivering a synthesis and recommendation", p: "The interviewer says: 'The CEO of a regional ferry operator just walked in; give me your recommendation on whether to replace two old diesel ferries with electric ones.' How do you structure a 60-second synthesis?", d: 1, tp: "case-structuring", i: "Lead with the answer, then give two or three supporting reasons, then risks and next steps. For example: 'I recommend replacing them with electric vessels only on the two shortest routes, because the economics work there. First, the shorter routes have predictable energy needs that current batteries meet, and fuel plus maintenance savings should pay back the higher capex within about a decade assuming subsidy support. Second, regulatory and customer pressure on emissions is rising, so waiting increases stranded-asset risk. Third, charging infrastructure at the two terminals is the critical dependency. The main risks are grid connection delays and battery degradation costs, which I would mitigate with a staged contract and a performance guarantee. Next steps are a detailed charging feasibility study and a lifecycle cost model.' Use a top-down, pyramid shape, quantify where you can, do not restate the whole case, and be brief and decisive while naming risks honestly.", c: ["Answer first, then supporting reasons", "Two or three key arguments with evidence", "Name main risks and mitigations", "Close with concrete next steps"], k: ["Top-down pyramid communication suits senior listeners", "Concise and decisive, not a recap of the analysis"], m: ["Walking through the analysis chronologically before giving the answer", "Giving a recommendation with no risks or next steps"] },
  { t: "Structure: garden-supplies chain losing market share", p: "A regional garden-supplies retail chain with 40 stores has seen sales stay flat for three years while the overall regional market grew about 6 percent a year. The CEO asks why the company is losing share. Structure your approach.", d: 1, tp: "case-structuring", i: "Share loss means sales growth below the market, so split into market versus company factors and then into customers, offer and channel. Structure: (1) Where is the share going: by category, region, store, and customer segment (homeowners, landscapers, new gardeners). (2) Competitors: new entrants such as big-box chains, online specialists and supermarkets, their pricing, range and store openings. (3) Customer: have preferences shifted (online ordering, sustainable and native plants, smaller gardens), and has the footfall or conversion changed. (4) Our offer: range, price perception, quality of plants, availability, service advice, and loyalty. (5) Operations and channels: store condition, stock-outs, absence of online or click-and-collect. Hypothesis: share loss is concentrated in online-friendly categories and in areas with new big-box competition, driven by weaker price perception and lack of omnichannel. First analyses: sales and market share by category and region against competitor openings; footfall versus conversion versus basket trend; price index versus key competitors; and customer survey on reasons for switching.", c: ["Define share loss as growth below market", "Split by segment, category and region to locate the loss", "Cover competitors, customers, own offer and channels", "State a hypothesis and first analyses"], k: ["Locate the problem before diagnosing the cause", "Decompose sales into footfall, conversion and basket"], m: ["Jumping to price cuts without locating where share is lost", "Ignoring that the market itself is growing"] },
  { t: "Structure: hospital emergency department waits", p: "A 400-bed public hospital reports that median waiting time in its emergency department has risen from 2 to 4.5 hours over eighteen months. The board wants to know how to fix it. Structure your approach.", d: 2, tp: "case-structuring", i: "Treat it as a flow problem: demand arriving, capacity processing, and downstream outflow. Structure along the patient journey: (1) Demand: arrivals by volume, acuity and time of day, including any growth in low-acuity patients who could be treated elsewhere. (2) Front end: triage speed, registration and the share of patients waiting to be seen versus waiting for results. (3) Treatment capacity: doctors, nurses and rooms by shift against demand peaks, plus diagnostics (imaging and lab turnaround). (4) Exit: admission delays because inpatient beds are full ('boarding'), and delays discharging inpatients, which is often the biggest hidden driver. Also include external factors such as closure of nearby urgent-care centres. Hypothesis: the main cause is bed blocking, with admitted patients stuck in the department because wards lack discharge capacity. First analyses: waiting time split into stages (arrival to triage, triage to doctor, doctor to decision, decision to departure), staffing against arrival curves, and number of boarding hours per day. Fixes depend on which stage dominates.", c: ["Frame as patient flow: demand, capacity, exit", "Journey stages: triage, treatment, diagnostics, admission", "Include downstream bed availability and discharge", "Hypothesis plus stage-split of wait times"], k: ["Find the bottleneck stage before choosing solutions", "Waits are often caused outside the department"], m: ["Assuming the answer is simply more emergency staff", "Treating average waiting time as one undifferentiated number"] },
  { t: "Structure: SaaS company with rising churn", p: "A B2B project-management software company with 5,000 customers has seen annual revenue churn rise from 8 to 15 percent. The CEO asks you to identify the causes and propose a plan. Structure your approach.", d: 1, tp: "case-structuring", i: "Start by locating the churn, then explain it. (1) Who is churning: by customer size, industry, plan, tenure cohort, region, and whether it is logo churn or downgrade (revenue churn). (2) Why: product (missing features, bugs, performance), competitors (new entrants, price cuts, bundling by larger suites), customer-side (budgets, layoffs, M&A), commercial (price rises, contract terms, discounting that expired) and service (support quality, onboarding). (3) When in the lifecycle: early churn signals poor onboarding, renewal-point churn signals value perception or price. (4) What we can do: retention levers such as onboarding, customer success coverage, product fixes, pricing and contract design, and win-back. Hypothesis: churn rise is concentrated in small customers acquired through discounted campaigns during the last two years who never adopted the product fully. First analyses: cohort retention curves, churn by segment and acquisition channel, usage data of churned versus retained accounts, and exit interview themes.", c: ["Locate churn by segment, cohort and plan", "Causes: product, competition, customer, commercial, service", "Lifecycle timing of churn", "Retention levers and first analyses"], k: ["Cohort analysis separates acquisition quality from product issues", "Distinguish logo churn from revenue churn"], m: ["Assuming price is the only reason customers leave", "Treating churn as a single average number"] },
  { t: "Structure: airline considering a new route", p: "A mid-sized European airline is evaluating launching a daily service between a secondary city in its network and a large Gulf hub. How would you structure the analysis to advise on whether to launch?", d: 2, tp: "case-structuring", tp2: "case-strategy", i: "The decision is whether the route earns an acceptable return, so structure around demand, competition, economics and feasibility. (1) Market demand: passenger volumes on the city pair including connecting traffic via the Gulf hub, business versus leisure mix, seasonality, and cargo belly capacity. (2) Competition: existing direct and one-stop options, their frequency, fares and likely response, plus whether the hub carrier would codeshare or compete. (3) Economics: expected load factor and yield versus unit cost, aircraft availability and opportunity cost of using the aircraft elsewhere, airport charges, and slot or bilateral rights. (4) Feasibility and strategy: regulatory approval, fit with network and brand, partnerships, and risk of cannibalising existing routes. Hypothesis: the route is viable only if a codeshare feeds connecting traffic, since point-to-point demand alone cannot fill the aircraft at a profitable yield. First analyses: addressable demand from booking data, break-even load factor, and opportunity cost of the alternative route for the same aircraft.", c: ["Demand sizing including connecting traffic", "Competitive landscape and likely response", "Route economics: break-even load factor and opportunity cost", "Feasibility, rights, partnerships and cannibalisation"], k: ["Opportunity cost of aircraft is central to route decisions", "Compare against the best alternative use, not zero"], m: ["Only looking at point-to-point demand", "Ignoring slot and traffic-right constraints"] },
  { t: "Structure: bakery chain choosing expansion path", p: "A successful five-shop artisan bakery in one city wants to grow. The founders are considering opening more shops, selling through supermarkets, or franchising. Structure how you would help them decide.", d: 1, tp: "case-structuring", i: "Treat it as choosing between options against common criteria. First agree the objective (profit, growth rate, brand protection, founder involvement) and constraints (capital, management time, quality control). Then for each option assess: market attractiveness (size and growth of the demand reachable), economics (investment, unit margin, payback), ability to win (brand strength, production capacity, supply of skilled bakers), and risks (quality dilution, cannibalisation, channel conflict, dependence on a retailer's terms). Own shops give control and high margins but are capital-intensive and slow; supermarket supply scales fast but with low margins, retailer power and a risk to artisan positioning; franchising scales with little capital but needs strong systems and brand control. Hypothesis: a hybrid, opening a few more shops in nearby cities while testing a limited supermarket line of long-shelf-life products, balances growth and brand. First analyses: unit economics of an existing shop, supermarket margin and volume terms, and franchisee economics versus support cost.", c: ["Clarify objectives and constraints", "Common criteria for comparing options", "Economics, ability to win and risk per option", "Hypothesis and first analyses"], k: ["Evaluate options on the same criteria for comparability", "Brand and quality control are key constraints for artisan businesses"], m: ["Choosing on growth potential alone", "Ignoring the capital and management constraints"] },
  { t: "Structure: insurer facing rising claims costs", p: "A motor insurer's loss ratio (claims divided by premiums) has risen from 68 to 82 percent over two years, wiping out profit. How would you structure the investigation and what would you check first?", d: 2, tp: "case-structuring", i: "Loss ratio = claims cost / premiums, so decompose both. Claims: frequency (claims per policy) times severity (average cost per claim). Premiums: number of policies times average premium, including recent price changes and mix. Structure: (1) Frequency: more accidents because of driver mix, traffic recovery, or weather; fraud; new-customer adverse selection. (2) Severity: repair costs and parts inflation, injury claim settlements, garage and supplier rates, claims handling leakage. (3) Premium side: whether pricing has lagged inflation, discounting to win customers, and mix shift to riskier segments, or an acquisition channel that attracted worse risks (such as price comparison sites). (4) Reserving and accounting: changes in reserve releases that mask or exaggerate the picture. Hypothesis: severity inflation from parts and labour is outpacing rate increases while growth from comparison sites added riskier drivers. First analyses: frequency and severity trend by segment and channel, average premium versus claims inflation, and loss ratio by customer cohort.", c: ["Loss ratio decomposed into claims and premiums", "Claims split into frequency and severity", "Premium adequacy and mix shift", "Segment and cohort analysis as first step"], k: ["Segment by channel and cohort to find adverse selection", "Check reserving effects before concluding"], m: ["Treating the loss ratio as a single driver", "Ignoring pricing lag versus claims inflation"] },
  { t: "Structure: university with falling enrolment", p: "A mid-ranked public university's undergraduate enrolment has fallen 12 percent in four years, threatening its budget. The president asks for a plan to reverse the trend. Structure your approach.", d: 2, tp: "case-structuring", i: "Enrolment is the product of applicants, offer rate and acceptance (yield), plus retention of enrolled students. Structure as a funnel with causes: (1) Demand: demographic decline of the age cohort, competing options such as apprenticeships and online degrees, perceived value of a degree. (2) Applications: awareness and reputation, programme portfolio versus demand for subjects, geographic reach, and marketing. (3) Conversion: offer policy, tuition and aid relative to competitors, speed of offers, location and housing. (4) Retention: dropout by year, student satisfaction, academic support. (5) Financial constraints and what is controllable. Hypothesis: the main loss is in yield and first-year retention in programmes where peer institutions offer better aid, since total applicant numbers are only slightly down. First analyses: funnel conversion by programme and year, competitor cross-application data, aid packages versus rivals, and first-year dropout reasons. Solutions differ greatly depending on whether the leak is at awareness, yield or retention.", c: ["Funnel: applicants, offers, yield, retention", "External demand factors such as demographics and alternatives", "Programme, pricing and aid competitiveness", "Hypothesis and funnel analyses"], k: ["Find the leaky funnel stage before designing solutions", "Retention is as important as intake for headcount"], m: ["Focusing only on marketing to attract applicants", "Overlooking dropouts as part of enrolment decline"] },
  { t: "Structure: bike-share operator entering a new city", p: "A bike-share operator, currently active in three mid-sized cities, is deciding whether to launch in a fourth city of 1.5 million people. Structure the analysis to recommend go or no-go.", d: 2, tp: "case-structuring", tp2: "case-strategy", i: "Frame around market attractiveness, ability to win and economics. (1) Market: city size and density, geography (hills, climate), cycling culture and infrastructure (lanes), commuting patterns, tourist flows, and regulation including permits and fleet caps. (2) Competition and substitutes: incumbent operators, e-scooters, public transport coverage, and the city's attitude to a possible exclusive franchise. (3) Economics: fleet size needed for coverage, revenue per bike per day (rides times average fare), costs of rebalancing, maintenance, theft and vandalism, charging for e-bikes, and local operations team; payback period versus the other cities. (4) Ability to win and risks: operational playbook transferability, partnerships with the city or transit authority, brand, and exit costs if the permit is withdrawn. Hypothesis: go, only if the city grants a multi-year permit with a cap on competitors, since density supports about 4 rides per bike per day, which is above break-even. First analyses: demand estimate from commuting data, unit economics versus current cities, and the regulatory outlook.", c: ["Market attractiveness including infrastructure and regulation", "Competition and substitutes", "Unit economics: rides per bike per day versus cost", "Risks, exit costs and playbook transferability"], k: ["Benchmark unit economics against existing cities", "Regulation can make or break local mobility businesses"], m: ["Estimating demand from population alone", "Ignoring rebalancing and vandalism costs"] },
  { t: "Structure: copper mine with falling output", p: "A copper mine owned by a mid-tier mining company has produced 15 percent less refined copper this year than last, despite no change in capacity. The CFO wants to understand why. Structure your approach.", d: 2, tp: "case-structuring", i: "Output = ore mined x ore grade x recovery rate (through concentrating and refining) x uptime, so decompose along the value chain. (1) Mining: tonnes moved, equipment availability, pit conditions, haul distance, labour or strike effects, weather. (2) Ore quality: average grade declining as the pit deepens or as lower-grade zones are mined, ore blending decisions. (3) Processing: mill throughput, recovery rate, downtime, reagent quality, water availability. (4) Refining and logistics: smelter capacity, bottlenecks in transport and stockpiles, and measurement or accounting effects such as timing of inventories. Hypothesis: falling grade is the main cause because the mine plan shifted to lower-grade areas to reduce stripping costs. First analyses: monthly tonnes mined, grade and recovery trends to isolate which factor explains most of the 15 percent; availability of key equipment; and comparison of planned versus actual mine sequencing. Then evaluate whether the trade-off was deliberate and whether fixing it pays given copper price.", c: ["Output equation: tonnes, grade, recovery, uptime", "Mining, processing and refining stages", "Ore grade and mine plan as a hypothesis", "Variance analysis of plan versus actual"], k: ["Decompose the 15 percent into drivers using the equation", "Some declines are deliberate trade-offs with cost"], m: ["Assuming equipment failure without evidence", "Ignoring ore grade and recovery"] },
  { t: "Structure: hotel group with weak occupancy", p: "A group of twelve business hotels in secondary cities reports occupancy falling from 74 to 61 percent while room rates have been held flat. What structure would you use to diagnose the problem?", d: 1, tp: "case-structuring", i: "Occupancy is demand captured divided by capacity, so ask who stopped coming and why. (1) Demand by segment: corporate contracts, group and event bookings, leisure, and online travel agency traffic, by city and property. (2) Market: has local demand fallen (a major employer closing, remote work, fewer conferences) or is market occupancy stable while we lose share? (3) Competition: new hotels, serviced apartments, and platforms such as short-term rentals. (4) Our offer: room quality, reviews and ratings, location, price relative to comparable hotels, and loyalty offerings. (5) Channels and revenue management: distribution mix, visibility online, and whether rate parity or lack of dynamic pricing hurts. Hypothesis: corporate travel has declined and competitors with fresher rooms and better reviews are taking the remaining demand, while our flat rate gives us no dynamic response. First analyses: occupancy and revenue per available room against the competitive set by city, bookings by segment and channel, and review scores trend.", c: ["Segment demand by customer type and channel", "Market versus share-loss distinction", "Competition and own offer", "Revenue management and first analyses"], k: ["Compare against the local competitive set to separate market from share", "Flat rates in a falling market may signal missing dynamic pricing"], m: ["Assuming a discount will fix demand", "Looking at group averages instead of hotel and city level"] },
  { t: "Structure: drug maker facing generic competition", p: "A pharmaceutical firm's best-selling hypertension drug loses patent protection in 18 months. The head of the business unit asks what the company should do. How would you structure the problem?", d: 3, tp: "case-structuring", tp2: "case-strategy", i: "Define the objective as maximising the value of the franchise through and beyond patent expiry. Structure: (1) Expected erosion: market size, likely generic entrants and number, price discount curves by market, share loss speed (for example 80 to 90 percent volume loss within a year in the US, slower in markets with brand loyalty or prescriber habits), and the revenue cliff. (2) Defend: lifecycle management through new formulations, combination pills, extended-release versions, paediatric extensions, patents on secondary uses, and an authorised generic or tie-up with a generics player. (3) Shift: move sales force and marketing spend to successor products and launch pipeline, and consider price tiering to keep volume in some markets. (4) Harvest or divest: cut cost to serve, sell the brand to a specialist in off-patent products, and value it. (5) Financial and strategic implications: impact on earnings, R&D funding, and portfolio gaps. Hypothesis: a staged approach, with a defensive authorised generic in the US and a divestment of mature ex-US markets, preserves most near-term cash. First analyses: erosion model by market, value of lifecycle options against cost and probability of success, and bidders' valuations for divestment.", c: ["Model revenue erosion after expiry by market", "Defend options: lifecycle management and authorised generics", "Shift resources to pipeline products", "Harvest or divest alternatives with valuation"], k: ["Market-by-market differences change the optimal action", "Compare options by value, probability of success and cost"], m: ["Assuming erosion is uniform across markets", "Ignoring divestment as a value-preserving option"] },
  { t: "Structuring when no standard framework fits", p: "You are given a case about whether a city council should create a municipal broadband network. None of the famous frameworks seem to apply neatly. How would you build a structure from scratch, and what does that process demonstrate?", d: 3, tp: "case-structuring", tp2: "case-strategy", i: "Start from the decision and the objective: should the council invest, and by what criterion (social benefit, financial return, coverage)? Then ask what would have to be true for yes to be right, and group those conditions into MECE buckets that fit this case rather than forcing a template. For municipal broadband the conditions are: a need exists (coverage gaps, speeds, prices versus alternatives), the council can deliver (technical capacity, capital, procurement and operating ability), the economics work (take-up rates, price per household, build cost per home passed, payback, and whether private providers would respond with price cuts), and the council is the right actor (alternatives such as subsidising a private operator or open-access wholesale, and legal or state-aid constraints). Add risk and stakeholder branches. Hypothesis: the council should only build in underserved areas where private investment is absent, perhaps through a public-private partnership. This process shows that you reason from the decision backwards, check logic with MECE, tailor the structure to the context and can articulate a hypothesis, which matters more than knowing a named framework.", c: ["Start from the decision and success criterion", "Derive branches from what must be true for yes", "Tailor buckets to the context and test for MECE", "State a hypothesis and the analyses that test it"], k: ["Frameworks are scaffolding, a custom issue tree is often better", "Include alternatives to the proposed action, not only the action itself"], m: ["Forcing 4Ps or Porter onto a case where it does not fit", "Structuring without a clear decision to answer"] },
  { t: "Adapting your structure when data disproves it", p: "Midway through a case on a declining chain of dry cleaners, the interviewer gives you data showing that customer numbers and prices are both stable, which contradicts the hypothesis you stated. What do you do?", d: 2, tp: "case-structuring", i: "Acknowledge it plainly: 'That tells me revenue is not the driver, so the problem likely sits in costs or in the mix.' Then update the structure rather than abandoning it: mark the revenue branch as largely eliminated, restate what remains (cost per garment by labour, solvent and chemicals, rent and utilities, equipment maintenance, store-level productivity), and pick the next most likely branch with a quick rationale, for example rising rent and energy costs or labour hours. Ask for the specific data that would discriminate, such as cost lines over time or per-store costs. Check that stable customer numbers do not hide a mix shift to cheaper services, since stable averages can hide shifts. Show a calm, iterative approach: a refuted hypothesis is progress because it narrowed the search. Avoid defending the old hypothesis, forcing the data to fit, or restarting from zero. Finally, restate the new hypothesis and what you will do next.", c: ["Acknowledge the data and what it eliminates", "Update structure and mark closed branches", "Pick next branch with reasoning and request data", "Check for hidden mix effects"], k: ["Refuting a hypothesis narrows the problem", "Stay calm and iterative rather than defensive"], m: ["Defending the original hypothesis against the evidence", "Starting over without using what was learned"] },
  { t: "Structure: consumer-goods firm deciding whether to sell a brand", p: "A diversified consumer-goods company owns a mid-sized frozen-dessert brand that grows 1 percent a year and earns below-average margins. The board asks whether to sell it. Structure the question.", d: 3, tp: "case-structuring", tp2: "case-strategy", i: "The core test is whether the company is the best owner and whether selling yields more value than keeping. Structure: (1) Value of keeping: market growth and position of the brand, margins and potential to improve with fixes (pricing, range, cost, distribution), cash generation, and strategic synergies such as shared distribution or manufacturing. (2) Value of selling: likely buyers (strategic and private equity), valuation multiples, price range, taxes, stranded costs and dis-synergies from separating shared infrastructure, and use of proceeds, including returns from reinvesting or paying down debt. (3) Strategic fit: role in portfolio, link to core capabilities, and management attention consumed. (4) Alternatives: improve then sell, joint venture, or licence. (5) Risks: employee and customer effects, execution of separation, and timing in the market cycle. Hypothesis: sell, provided the net proceeds exceed the discounted value of an improved standalone and stranded costs are manageable. First analyses: standalone value with and without a turnaround plan, buyer valuation benchmarks, and quantification of shared costs and synergies.", c: ["Compare value of keeping versus selling", "Fit with portfolio and ownership advantage", "Buyers, valuation, stranded costs and taxes", "Alternatives such as fix then sell or joint venture"], k: ["Best-owner logic drives divestment decisions", "Include stranded costs that are easy to forget"], m: ["Deciding on growth rate alone", "Ignoring alternatives to a straightforward sale"] },
  { t: "Structure: delivery company with late parcels", p: "A national parcel-delivery company finds that 14 percent of parcels in its two largest cities arrive after the promised date, up from 5 percent a year ago. Structure how you would find the root cause.", d: 2, tp: "case-structuring", i: "Follow the parcel through the network and compare supply of capacity with demand. (1) Demand: volume growth, peaks (promotions, holidays), changes in customer mix such as bulkier items, and address density. (2) Collection and inbound: pick-up reliability and cut-off times. (3) Hubs and sorting: capacity utilisation, automation breakdowns, sortation errors and dwell time. (4) Linehaul: truck availability, route design, schedule adherence and driver shortages. (5) Last mile: driver numbers and turnover, route density, failed delivery attempts, congestion, and accuracy of address data. (6) Promise side: whether delivery dates promised to customers were made tighter without capacity. Hypothesis: last-mile capacity in the two cities has not kept up with parcel growth because of driver attrition, so routes are too long to finish. First analyses: lateness by stage using scan data to identify where time is lost, by city, depot and day of the week, and volume versus driver hours. Then evaluate fixes by stage such as depot expansion, route optimisation, extra drivers or revising service promises.", c: ["Decompose along the parcel journey", "Demand versus capacity at each stage", "Promise setting as a hidden driver", "Scan-data analysis to locate where delay arises"], k: ["Find the stage where time is lost before designing solutions", "A tighter delivery promise can create lateness without any operational change"], m: ["Blaming drivers without data on where delays accumulate", "Looking only at national averages"] },

  { t: "Profitability: craft brewery with squeezed margins", p: "A craft brewery sells its beer in bottles and kegs to pubs and supermarkets. Revenue is up 8 percent over two years but net margin fell from 12 to 5 percent. What drives this and how would you approach the problem?", d: 1, tp: "case-strategy", i: "Decompose margin change into price, volume, mix and cost effects. Revenue could be growing through volume to supermarkets (lower price per litre) while pubs, which pay more, are buying less. Costs: raw materials (barley, hops, glass and aluminium, which inflated recently), energy and brewing costs, distribution, marketing and trade discounts, and fixed overheads from added capacity. Approach: build a profit bridge from two years ago to now; compute margin per litre by channel and package; review cost per litre by line item; and compare pricing to input cost increases. Likely hypothesis: supermarket growth at thin margins plus input inflation without matching price rises explains most of the decline. Recommendations might include repricing or reducing promotional depth with supermarkets, shifting mix towards higher-margin kegs and pubs or premium products, renegotiating packaging contracts, and improving brewing yield. Prioritise by margin impact and ease, then quantify the combined effect against the 7-point gap.", c: ["Profit bridge across price, volume, mix and cost", "Margin per litre by channel and package", "Input cost inflation versus pricing", "Levers: repricing, mix, procurement, yield"], k: ["Growth in a low-margin channel can destroy profit", "Quantify levers against the size of the margin gap"], m: ["Assuming more volume fixes margin", "Cutting costs everywhere without finding the source"] },
  { t: "Profitability: cinema chain with fewer profits", p: "A cinema chain of 60 multiplexes has seen admissions recover to 85 percent of pre-pandemic levels while profit remains at 40 percent of the earlier level. What explains this gap and what would you recommend?", d: 2, tp: "case-strategy", i: "Cinema economics: ticket revenue (shared with studios, often 50 percent or more of box office), concession revenue (high margin, roughly 70 percent or more), advertising and costs largely fixed (rent, staff, utilities). With admissions at 85 percent, revenue per head matters more than volume. Likely drivers: weaker film slate and shorter windows reduce high-demand weekends; higher studio rental terms; lower concession spend per head; reduced advertising income; and increased wages and energy cost. Fixed costs mean a 15 percent admissions shortfall hits profit disproportionately, as operating leverage works in reverse. Approach: profit bridge by revenue line and cost line, site-level profitability, and utilisation by time slot. Actions: raise concession attach rates and average spend through combos and premium formats; shift to premium large-format screens and event cinema; cut showings in low-demand slots to match labour to occupancy; renegotiate rents and close persistently unprofitable sites; add alternative revenue such as venue hire or gaming. Quantify each and note risks like alienating price-sensitive customers.", c: ["Revenue lines: tickets, concessions, advertising", "Operating leverage from largely fixed costs", "Site-level profitability and time-slot utilisation", "Levers: concessions, premium formats, scheduling, closures"], k: ["High fixed cost means small volume drops hit profit hard", "Concessions drive profit more than ticket sales"], m: ["Focusing only on admissions volume", "Treating all sites as equally profitable"] },
  { t: "Pricing: tiered pricing for B2B software", p: "A start-up sells analytics software to mid-sized manufacturers at a flat 2,000 dollars per month per company. Larger customers use it much more heavily and some small ones barely use it. The CEO wants a new pricing model. How do you approach this?", d: 1, tp: "case-strategy", i: "Pricing should align with the value customers get and capture willingness to pay across segments. Flat pricing leaves money on the table from heavy users and loses small users who see too little value. Approach: segment customers by size and usage, identify a value metric that grows with value received (number of machines monitored, users, data volume), and research willingness to pay through interviews and conjoint analysis. Options: tiered plans (good, better, best) with feature gating; usage-based pricing; or a hybrid with a platform fee plus a usage component. Evaluate against criteria: revenue impact, predictability for customers, simplicity to sell, competitor prices and risk of churn at the low end. Check cost to serve, as heavy users cost more. Recommendation: a three-tier model anchored to machines monitored, with a low entry tier to retain small customers and an enterprise tier with support. Pilot with new customers first and grandfather existing ones to limit churn, then monitor conversion and upgrade rates.", c: ["Segment by usage and value received", "Choose a value metric tied to value", "Evaluate tiered, usage-based and hybrid models", "Pilot, grandfather existing customers and monitor"], k: ["Price metric should scale with customer value", "Balance revenue upside against churn and simplicity"], m: ["Setting price from cost alone", "Switching all customers at once without a pilot"] },
  { t: "Pricing: raising prices on a meal-kit subscription", p: "A meal-kit subscription firm pays 12 percent more for ingredients and delivery than a year ago and its margin is thin. The CFO proposes a 10 percent price increase across the board. Evaluate and recommend.", d: 2, tp: "case-strategy", i: "Test whether the increase is profitable by estimating the churn it causes. Break-even: with contribution margin m (percent of revenue), a price increase of p percent is profitable if volume loss is below p / (m + p). If contribution margin is 30 percent and the increase is 10 percent, volume can fall up to 10/40 = 25 percent before profit drops, which is a lot, so the rise is likely profitable unless elasticity is very high. Then examine elasticity by segment: heavy loyalists likely less sensitive than promotion-acquired customers, and competitor prices matter (do rivals face the same cost inflation and will they follow?). Consider smarter alternatives to an across-the-board rise: targeted increases, smaller portion options, removing deep discounts for new customers, delivery fees, or reducing ingredient cost through recipe redesign. Test with an A/B price experiment on a sample before roll-out, watch churn, pause rates and order frequency, and communicate the reason transparently. Recommend a staged, segmented increase paired with cost actions.", c: ["Break-even volume loss: p / (m + p)", "Elasticity by customer segment", "Competitor reaction and cost pass-through", "Test via experiment and consider alternatives"], k: ["Contribution margin determines how much volume loss is tolerable", "Segment-based increases limit churn among sensitive customers"], m: ["Assuming every price increase loses profit through churn", "Ignoring the effect on lifetime value, not just short-term revenue"] },
  { t: "Pricing: premium sensor for industrial use", p: "A manufacturer has developed a vibration sensor that predicts machine failures and cuts unplanned downtime by about 30 percent. Competitors' basic sensors sell for 200 dollars. How should the company set the price and what pitfalls should it avoid?", d: 3, tp: "case-strategy", i: "Use value-based pricing rather than cost-plus. Estimate the customer's economic value: annual cost of unplanned downtime (for a plant, say 500,000 dollars) multiplied by a 30 percent reduction gives 150,000 dollars of avoided cost; that is the economic value versus the next best alternative. The price should sit between the competitor's price and total value, sharing the surplus so that the customer sees a compelling return (often capturing 20 to 40 percent of the surplus while the buyer keeps the rest). Validate with customers: willingness to pay interviews and pilot installations to verify the benefit claim. Consider structure: hardware priced near market with a subscription for analytics, or outcome-linked pricing, which reduces the buyer's risk but exposes the seller. Segment by downtime cost since value varies; a bottling plant with expensive stoppages pays more than a small workshop. Pitfalls: pricing near the 200 dollar competitor anchor, claiming savings without proof, ignoring installation and integration costs for the customer, and failing to align sales incentives. Check competitor response and the cost to serve the analytics.", c: ["Value-based pricing: quantify customer economic value", "Price between next best alternative and total value", "Validate claims with pilots and willingness-to-pay research", "Segmentation and subscription or outcome-based models"], k: ["Value to the customer varies, so price structure should capture that", "Share the surplus so the buyer has a clear return"], m: ["Using cost-plus pricing for a differentiated product", "Anchoring on competitors' basic sensors"] },
  { t: "Market entry: Nordic skincare brand into South-East Asia", p: "A premium Nordic skincare brand sells in Europe and wants to enter Southeast Asia. It is considering Singapore, Thailand and Indonesia. How would you decide whether and how to enter?", d: 2, tp: "case-strategy", i: "Assess market attractiveness, ability to win and entry mode. Attractiveness: market size and growth of premium skincare, disposable income, climate-specific needs (humidity, sun care, brightening preferences), regulatory requirements for cosmetics registration, and import duties. Competition: strong Korean and Japanese brands, local players, and price positioning of premium Western brands. Ability to win: whether the brand's natural, clean positioning resonates, product fit for skin types and climate, and distribution access (department stores, specialty retailers like beauty chains, e-commerce marketplaces and social commerce). Entry mode: direct online sales through marketplaces (low investment, test quickly), distributor or retail partner (local knowledge, less control), or local subsidiary (high control, high cost). Prioritise: Singapore as a small but affluent test market and regional hub, followed by Thailand where premium demand is growing, with Indonesia later given scale but complex regulation and halal certification needs. Recommend a pilot through e-commerce in Singapore with a distributor in Thailand, set success metrics, and examine reformulation needs and marketing budget.", c: ["Market attractiveness by country", "Competition and brand fit", "Entry modes with trade-offs", "Sequenced entry with a pilot and metrics"], k: ["Sequence markets using attractiveness and ease of entry", "Local regulation and distribution shape the entry mode"], m: ["Treating Southeast Asia as one homogeneous market", "Entering with full local operations before testing demand"] },
  { t: "Market entry: regional bank into small-business lending", p: "A regional retail bank with a strong consumer franchise considers entering digital lending to small businesses (companies under 5 million in revenue). How would you evaluate this?", d: 2, tp: "case-strategy", i: "Evaluate attractiveness, right to win and economics. Market: number of small businesses in the bank's region, their funding needs, current penetration and satisfaction with incumbents and fintech lenders, and growth. Economics: net interest margin, fees, loss rates (small business default rates are higher and cyclical), cost of acquisition and servicing, and capital requirements; compute risk-adjusted return per loan and the minimum loan size at which unit economics work. Right to win: existing customer data (owners of businesses already banking with it), brand trust, deposit funding advantage, and gaps in credit scoring and underwriting capability for small firms; digital lenders use cash-flow data to approve quickly, which the bank would need to match. Risks: adverse selection if competitors skim the best borrowers, credit losses in a downturn, and regulatory requirements. Recommendation: start with existing customers, using internal data to pre-approve limited credit lines, then expand with partnered data sources. Pilot to validate default rates and acquisition cost before scaling.", c: ["Market size, penetration and incumbent satisfaction", "Risk-adjusted unit economics including loss rates", "Right to win: data, trust, funding advantage", "Pilot with existing customers before scaling"], k: ["Credit risk and underwriting capability determine profitability", "Existing customer data is a natural advantage"], m: ["Evaluating only on interest margin without losses", "Underestimating underwriting capability needs"] },
  { t: "Market entry: drone delivery for rural pharmacies", p: "A logistics start-up proposes launching drone delivery of prescription medicines from rural pharmacies to patients' homes in a large, sparsely populated region. Should investors back it? Outline your approach and the key judgments.", d: 3, tp: "case-strategy", i: "Test demand, economics, feasibility and regulation. Demand: how many patients are far from a pharmacy, prescription frequency (chronic patients need regular, planned refills, which are tolerant of delay, so speed may be less valued than assumed), willingness to pay versus the existing alternative of post delivery. Economics: cost per delivery equals drone depreciation, maintenance, battery, operators and insurance divided by deliveries per drone per day; compare with the cost of a courier or postal delivery (often a few dollars), and the number of deliveries per drone given range, payload limits, weather and the one-to-many supervision ratio. Feasibility and regulation: beyond-visual-line-of-sight approval, airspace rules, cold-chain handling, prescription verification and handover safety. Competition and substitutes: mail-order pharmacy, community transport and telehealth. Key judgment: the business works only where delivery volume density is high enough and regulation allows low operator ratios, which is unlikely in sparse regions. Recommendation: do not back a full launch; fund a limited pilot on emergency or time-critical routes with a clear target cost per delivery, and test whether health systems will pay.", c: ["Demand sizing and urgency of use case", "Cost per delivery built from drone utilisation and operators", "Regulation: beyond-visual-line-of-sight, safety, cold chain", "Compare to substitutes and recommend staged pilot"], k: ["Sparse geography undermines delivery density", "Planned refills reduce the value of speed"], m: ["Assuming novelty equals demand", "Ignoring regulation and weather limits on utilisation"] },
  { t: "Due diligence: private equity buying a dental clinic chain", p: "A private equity fund is considering buying a chain of 25 dental clinics for 60 million dollars. EBITDA is 8 million. What would you analyse and what would make you walk away?", d: 2, tp: "case-strategy", i: "At 7.5 times EBITDA, the question is whether earnings are sustainable and can grow. Business quality: revenue per dentist chair, utilisation, patient mix (private pay versus insurance), retention, payer contract terms and pricing power. Quality of earnings: dentist dependence (owner-dentists leaving would take patients with them), compensation structure and retention, clinic-level profitability (are a few strong clinics hiding weak ones), accounting adjustments, and maintenance capex such as equipment. Growth levers: add chairs, increase hygiene and cosmetic services, opening new clinics, and procurement savings from scale. Risks: regulation of ownership of dental practices, malpractice liability, insurer reimbursement cuts, and wage inflation as dentists are scarce. Value: model returns using EBITDA growth, debt capacity, exit multiple. Walk-away signals: heavy reliance on a few key dentists without retention agreements, declining same-clinic revenue, hidden compliance problems, or an asking price that implies unrealistic synergies. Conclude with a price range tied to a base case and downside case.", c: ["Clinic-level economics and utilisation", "Quality of earnings and dentist retention", "Growth levers and risks", "Walk-away conditions and valuation range"], k: ["Key-person dependence is the main risk in professional services roll-ups", "Return depends on EBITDA growth, leverage and exit multiple"], m: ["Relying on headline EBITDA without checking sustainability", "Assuming synergies justify any price"] },
  { t: "M&A: acquiring a rival coatings producer", p: "An industrial paint and coatings manufacturer wants to acquire a smaller competitor with 200 million dollars of revenue. Management says synergies will justify a 30 percent premium. How do you test this?", d: 3, tp: "case-strategy", i: "The premium transfers value to the seller, so the buyer wins only if synergies exceed it, are achievable, and are not just competitive gains that already exist. Value the target standalone (discounted cash flow or multiples), then quantify synergies by type: cost synergies (procurement of raw materials such as resins and pigments, plant consolidation, overhead, logistics) are most reliable; revenue synergies (cross-selling, wider distribution) are less certain and should be heavily discounted. Estimate one-off integration costs, timing and probability, and the present value net of costs. Compare: if standalone value is 300 million, a 30 percent premium costs 90 million, which requires synergies with present value above that, say 15 million of annual run-rate cost savings capitalised, only after integration costs. Check antitrust risk because combining competitors raises concentration; customer churn from supply disruption; cultural and key-talent issues; and environmental liabilities at plants. Recommend proceeding only if risk-weighted synergies exceed the premium with a margin of safety, and structure the offer with contingent elements or walk-away price.", c: ["Standalone value versus premium paid", "Cost versus revenue synergies and their reliability", "Integration costs, timing and risk weighting", "Antitrust, customer and environmental liabilities"], k: ["The acquirer pays the premium upfront while synergies are uncertain", "Cost synergies are more credible than revenue synergies"], m: ["Counting full synergies without integration costs", "Ignoring antitrust and customer attrition risk"] },
  { t: "Due diligence: acquiring a fitness app", p: "A large sports-apparel company is considering buying a subscription fitness app with 1.5 million paying users, growing 40 percent a year, for 400 million dollars. What are the key questions and how do you judge the valuation?", d: 3, tp: "case-strategy", i: "Subscription value is driven by retention, acquisition cost and monetisation, so scrutinise the metrics beneath the headline growth. Unit economics: average revenue per user, gross margin, customer acquisition cost, monthly churn and cohort retention, from which lifetime value follows; check LTV to CAC above 3 and payback in under a year. Quality of growth: is growth paid through advertising (fading as spend falls) or organic; do retention curves flatten or keep decaying; how much is annual-plan discounting or free trials counted as users? Product moat: engagement, content cost, competition from big platforms and free alternatives, dependence on app-store fees. Strategic fit and synergies: cross-selling apparel, using member data, retail integration; model these conservatively. Valuation: compare revenue multiples to peers but also run discounted cash flows with decaying growth, and test downside cases where churn is higher. Risks: privacy regulation of health data, key founders, and integration. Recommend a price range based on retention-adjusted economics, and consider an earn-out tied to retention to share risk with the sellers.", c: ["Unit economics: ARPU, CAC, churn, LTV", "Cohort retention and quality of growth", "Moat, competition and platform dependence", "Valuation methods, downside cases and earn-out"], k: ["Cohort curves reveal whether growth is sustainable", "Revenue multiples need to be tied to retention-adjusted economics"], m: ["Paying on user growth alone", "Counting synergies the buyer could achieve without the deal"] },
  { t: "New product launch: plant-based pet food", p: "A mid-sized pet-food company is considering launching a plant-based dog food line. How would you assess whether to launch and how to go to market?", d: 1, tp: "case-strategy", i: "Assess market, customers, economics and execution. Market: size and growth of premium and alternative pet food, the share of owners who care about sustainability or health, and demand evidence from adjacent human food trends. Customers: who buys (environmentally minded or health-motivated owners) and whether they will pay a premium; there is also a concern that owners worry about nutrition for dogs, so veterinary endorsement matters. Competition: existing niche brands, private label and the company's own premium lines (cannibalisation). Economics: ingredient and R&D costs, price premium achievable, margin versus core products, and minimum volume to cover launch investment. Execution: nutritional validation and regulatory claims, retail distribution (specialty stores and online first), marketing, and brand fit. Risks: low repeat purchase if dogs reject the food, and reputational damage from poor nutrition. Recommendation: launch a small pilot in online and specialty channels with vet-backed claims, measure repeat rate and trial conversion, and scale if repeat purchase and margin targets are met.", c: ["Market size and customer willingness to pay", "Competition and cannibalisation", "Unit economics and launch investment", "Nutrition validation, channel strategy and pilot"], k: ["Repeat purchase is the real test for consumable products", "Trust and credibility (vets) matter for pet nutrition"], m: ["Relying on overall interest in sustainability without evidence of purchase", "Ignoring cannibalisation of existing premium products"] },
  { t: "New product launch: smart thermostats from an energy utility", p: "A regional electricity and gas utility is considering selling smart thermostats and a home-energy app to its 2 million customers. Does this make sense and how would you test it?", d: 2, tp: "case-strategy", i: "Assess customer value, strategic rationale and economics. Customer value: thermostats can cut heating bills 10 to 15 percent, appealing to cost-conscious households, and utilities have trusted billing relationships and customer data. Strategic rationale: lower peak demand through demand-response programs (which reduces wholesale and capacity costs), improve retention against switching, and create a platform for further services such as solar and heat pump offers. Economics: hardware margins are thin and competitive (existing consumer brands), so value comes from subscriptions and avoided peak costs: estimate take-up rate (a few percent of customers), cost to acquire, revenue per customer, and the value per device of peak reduction. Right to win: trust, billing channel and installation partners versus lack of consumer-electronics capability and app experience. Risks: privacy concerns, regulation on using customer data and cross-selling, customer support burden. Recommendation: pilot with a partner device (not own hardware) offered through bill credits, measure take-up, energy savings and peak reduction, then scale the strongest value proposition.", c: ["Customer value and savings", "Strategic benefits: retention and demand response", "Take-up, margin and avoided peak cost economics", "Partner-led pilot and risks (privacy, support)"], k: ["The value often lies in avoided system costs, not hardware margin", "Partnering reduces capability risk"], m: ["Assuming hardware sales alone are profitable", "Ignoring data privacy and regulatory limits"] },
  { t: "Turnaround: regional newspaper in decline", p: "A regional newspaper has seen print circulation fall 8 percent a year and advertising revenue drop 15 percent over three years. It now loses money. The new CEO asks for a turnaround plan. What do you recommend?", d: 1, tp: "case-strategy", i: "Diagnose the revenue and cost structure, stabilise cash, and then reposition. Revenue: print subscriptions, print advertising, digital subscriptions, digital advertising, classifieds and events; costs: newsroom, printing and distribution (largely fixed per copy), sales and overheads. Immediate actions: cut costs where readers lose least, for instance reduce print days, consolidate printing, and outsource distribution. Then build a sustainable model: grow digital subscriptions with a paywall around local content that is hard to find elsewhere (council, schools, local sport), improve ad yield with local targeted products, and add new revenue streams such as events, newsletters and marketing services for small businesses. Estimate subscriber economics: how many digital subscribers at what price replace lost print revenue; the transition usually leaves a gap, so the plan must manage cash. Prioritise by speed and impact and measure with subscriber counts and churn. Risk: cutting the newsroom too deeply destroys the product. Recommend a staged plan with a clear cash runway and milestones, and consider partnership or sale if the digital gap cannot be closed.", c: ["Revenue and cost structure diagnosis", "Immediate cost actions and cash stabilisation", "Digital subscriptions and new revenue streams", "Risks of newsroom cuts and a cash runway"], k: ["Local content is the differentiator for regional news", "Stabilise cash before investing in growth"], m: ["Cutting editorial quality as the main cost lever", "Expecting digital advertising to replace print revenue"] },
  { t: "Turnaround: container-manufacturing firm in distress", p: "A shipping-container manufacturer faces losses after demand fell 40 percent while it has two plants running at 55 percent utilisation and high debt due in 18 months. What should it do?", d: 3, tp: "case-strategy", i: "Sequence the plan: protect liquidity, fix the cost base, then pursue strategic options. First, build a 13-week cash flow and understand covenant and refinancing risk; open negotiations with lenders early about extending maturities or waivers, since distress usually forces concessions. Operations: with fixed costs spread across low volume, consolidate production into one plant or mothball a line, aligning capacity to realistic demand (the unit contribution margin matters for deciding which volumes to keep); reduce working capital by cutting inventory and renegotiating payment terms. Commercial: lock in long-term contracts with shipping lines, diversify into specialised containers (refrigerated, tank, modular buildings) with higher margins, and examine pricing discipline. Strategic: assess asset sales (a plant or land), a merger with a competitor, or a financial restructuring including debt for equity. Judgments: whether demand is cyclical (container demand follows trade volumes and may recover) or structural, since this determines how much capacity to retire permanently versus mothball. Recommendation: stabilise cash within weeks, consolidate capacity while preserving restart options, and run a refinancing and diversification process in parallel.", c: ["Liquidity and refinancing as first priority", "Capacity consolidation versus mothballing", "Margin improvement through specialised products and pricing", "Cyclical versus structural demand judgment"], k: ["Cash and debt maturity set the timeline", "Preserve restart optionality if demand is cyclical"], m: ["Starting with growth strategy before cash is secure", "Assuming demand will return without evidence"] },
  { t: "Cost reduction: hospital supply costs", p: "A hospital group spends 300 million dollars a year on medical supplies and devices. Its CFO wants to reduce this by 10 percent without harming patient outcomes. How would you approach it?", d: 2, tp: "case-strategy", i: "Cut spend through price, volume and specification levers, while protecting quality. Start with a spend cube: by category (implants, consumables, drugs, equipment), by supplier, and by hospital, to find concentration and price variation. Price levers: consolidate purchasing across hospitals, renegotiate with fewer suppliers, benchmark prices paid for identical items (variation of 20 percent between sites is common), and use tenders. Volume and demand levers: reduce unnecessary use (waste, overstock, expired items), standardise ordering and inventory management. Specification levers: reduce variety, for example fewer implant brands where clinical outcomes are equivalent, a step that must involve clinicians to maintain trust and safety. Process levers: purchase-to-pay compliance (buying off-contract), consignment inventory and supplier-managed stock. Judgments: protecting clinical outcomes by involving clinical leaders and setting quality guardrails; deciding where to trade off supplier relationships. Target roughly a 10 percent saving by mixing 4 to 5 percent from pricing, 3 percent from standardisation and 2 percent from waste. Track savings against baseline with finance verification.", c: ["Spend analysis by category, supplier and site", "Price, volume and specification levers", "Clinician involvement and quality guardrails", "Savings baseline tracking"], k: ["Price variation for identical items across hospitals shows fast savings", "Clinical buy-in is needed for standardisation"], m: ["Cutting supplies indiscriminately", "Claiming savings without a verified baseline"] },
  { t: "Cost reduction: customer service call centre", p: "An internet provider's call centre handles 6 million calls a year at 7 dollars per call and satisfaction is falling. The COO wants a 25 percent cost cut. How would you approach it?", d: 1, tp: "case-strategy", i: "Reduce cost per contact and the number of contacts, while maintaining satisfaction. First, analyse why customers call: categorise call reasons (billing queries, outages, setup problems, cancellations) and see what share is avoidable. Reduce demand: fix root causes such as confusing bills, proactive outage notifications, better online self-service and chat, and improved onboarding instructions; every avoided call saves the full cost. Reduce cost per call: shorten handling time via better tools and scripts, increase first-call resolution (repeat calls inflate volume), optimise staffing to demand curves, and consider moving some capacity to lower-cost locations or partners for simple tasks. Balance with quality: measure satisfaction, resolution and churn effect, because cutting cost by hurting service increases customer loss. Example: eliminating 15 percent of calls through self-service and bill fixes and reducing cost per call by 12 percent yields about 25 percent savings. Prioritise root-cause fixes first because they improve satisfaction and cost simultaneously, then sequence efficiency measures.", c: ["Call reason analysis and avoidable contacts", "Self-service and root-cause fixes", "Cost per call: handling time, first-call resolution, staffing", "Protect satisfaction and measure churn"], k: ["The cheapest call is the one that never happens", "First-call resolution reduces volume and improves satisfaction"], m: ["Cutting headcount without addressing call drivers", "Offshoring everything regardless of quality"] },
  { t: "Cost reduction: auto-parts plant", p: "An auto-parts plant making brake components has a 14 percent cost disadvantage versus the best competitor. The plant manager asks where the gap could come from and how to close it. How do you proceed?", d: 2, tp: "case-strategy", i: "Break the cost gap down by cost element then by cause. Elements: materials (steel, castings), direct labour, energy, overhead and logistics, scrap and rework, and depreciation. Benchmark each against the competitor or industry data: for example, materials 60 percent of cost, labour 15 percent. Causes: purchase price versus volume, yield loss and scrap rate, labour productivity (output per hour, automation level, changeover times), equipment efficiency (overall equipment effectiveness), plant scale and utilisation, and wage differences by location. Analyses: process mapping, time studies, value-stream mapping to find waste, and a scrap and downtime Pareto chart. Levers: negotiate or dual-source materials, reduce scrap through process control, improve changeovers (single-minute exchange of dies), invest in automation where payback is under three years, improve preventive maintenance, and raise utilisation by consolidating products. Separate structural gaps (location wages) from controllable ones, and prioritise by savings versus capex. Close the gap in waves, with quick wins in scrap and procurement first.", c: ["Decompose the gap by cost element", "Benchmark against best competitor", "Operational levers: yield, OEE, changeovers, procurement", "Separate structural from controllable gaps"], k: ["Pareto analysis focuses effort on the biggest cost drivers", "Capex for automation should be justified by payback"], m: ["Cutting labour first without checking yield and efficiency", "Ignoring structural differences like wages and scale"] },
  { t: "Growth: stagnating coffee chain", p: "A coffee-shop chain of 150 outlets has had flat revenue for three years. The CEO wants to double revenue in five years. What growth options would you evaluate?", d: 1, tp: "case-strategy", i: "Revenue growth comes from more outlets, more sales per outlet, and new businesses. Same-store growth: traffic (loyalty program, morning commuter offers, mobile ordering), average ticket (food attachment, premium drinks, upsell), and dayparts (afternoon and evening). New outlets: whitespace analysis in cities where the chain is under-represented, including formats such as drive-through and kiosks, and economics of each new store (investment, payback, cannibalisation). New channels: retail packaged coffee, delivery, and corporate supply. New products or adjacent services. Doubling in five years requires about 15 percent annual growth, so one lever alone is unlikely to suffice: perhaps 4 percent from same-store growth plus 10 percent from net openings plus some channel growth. Judgments: whether the flat revenue results from poor store performance (fix before expanding, as replicating weak units destroys value) and whether the brand has pull in new regions. Prioritise by return on investment and speed, and set metrics for each lever.", c: ["Same-store growth: traffic and ticket", "New stores with whitespace and unit economics", "New channels and products", "Required growth rate of about 15 percent per year"], k: ["Fix store-level performance before expanding", "Combine multiple levers to hit an ambitious target"], m: ["Assuming new stores alone solve flat revenue", "Ignoring cannibalisation of existing outlets"] },
  { t: "Growth: industrial distributor with a stalled core", p: "A distributor of fasteners and tools to small workshops has a 7 percent share of its regional market and flat revenue because the core market is mature. How would you identify growth opportunities?", d: 2, tp: "case-strategy", i: "List growth avenues using a structured lens: existing customers, new customers, new products and new geographies. Existing customers: increase share of wallet through wider range (adjacent categories such as safety equipment and abrasives), e-commerce reordering and vendor-managed inventory. New customers: segments underserved such as construction firms, maintenance contractors or e-commerce sellers, and smaller workshops that currently buy from retailers. New products: private-label lines with higher margin, value-added services such as kitting and technical advice. New geography: adjacent regions through bolt-on acquisition of small local distributors, which is common in fragmented distribution. Evaluate each by size of prize, margin, investment, and the company's right to win. In distribution, density matters: gaining share in existing territories lowers cost per delivery, so organic share gain and acquisitions in-region are attractive. Judgments: do not move into categories where manufacturers sell direct. Recommendation: start with share-of-wallet and private label (quick, high margin), pursue bolt-on acquisitions in adjacent regions, and track gross margin as well as revenue.", c: ["Growth matrix: customers, products, geographies", "Share of wallet and private label", "Bolt-on acquisitions and route density", "Prioritise by size of prize and right to win"], k: ["Density economics favour adding volume to existing routes", "Margin matters as much as revenue growth"], m: ["Chasing new categories without right to win", "Evaluating growth only by revenue"] },
  { t: "Competitive response: low-cost airline attacks an incumbent route", p: "A flag-carrier airline finds that a low-cost rival has begun flying the same short-haul route at fares 40 percent lower. The route earns 15 percent of the incumbent's profit. How should the incumbent respond?", d: 2, tp: "case-strategy", i: "Decide between matching, differentiating, retreating or counter-attacking, based on economics. First, size the exposure: how much of route traffic is price-sensitive leisure versus business and connecting passengers who value schedule, frequency, lounges and loyalty benefits. Then compare cost positions: the low-cost carrier's unit cost may be 30 percent lower, so a full price match loses money. Options: (1) Segmented response: match fares on a limited number of seats at off-peak times through a restricted fare class, protecting premium business fares. (2) Differentiate: schedule and frequency advantage, connectivity to the long-haul network, loyalty points, and services. (3) Launch or use a lower-cost sub-brand on the route. (4) Reduce capacity or exit if the route is unprofitable even after reasonable response. Also consider the signalling effect: aggressive response on this route may deter entry on others, while a weak response invites attacks. Recommendation: protect high-yield and connecting customers, offer limited fare matching, monitor load factors, and maintain a threshold for exiting the route if profit contribution including feed turns negative.", c: ["Customer segments by price sensitivity", "Cost position and economics of matching", "Segmented fare response, differentiation, sub-brand or exit", "Value of connecting feed and deterrence signalling"], k: ["Matching fully can lose more than the lost traffic", "Route value includes connecting passengers"], m: ["Assuming a full price match is the default", "Evaluating the route in isolation from the network"] },
  { t: "Competitive response: rival slashes prices on tyres", p: "A leading tyre manufacturer sees its main competitor announce a 12 percent price cut on passenger car tyres sold through independent dealers. How should the leader respond and what information do you need?", d: 2, tp: "case-strategy", i: "Start by understanding why the competitor cut: excess capacity, a push to gain share, cost advantage from a new plant, or a one-off promotion. The answer determines whether the cut is sustainable. Then estimate impact: volume at risk from price-sensitive dealers and consumers (elasticity), versus the margin lost if the leader matches. Compute break-even: if contribution margin is 35 percent, matching a 12 percent cut would require volume gains of roughly 52 percent to break even, which is impossible as the competitor already has the volume incentive, so matching broadly destroys profit. Options: hold price and defend through brand, quality and dealer relationships (loyalty bonuses, training); target price cuts to the specific segments and sizes under attack; introduce a second-line brand (fighter brand) for price-sensitive buyers; or compete on total cost of ownership such as mileage. Consider legal and competitive dynamics: avoid starting a price war with an equally capable rival. Recommendation: hold the premium brand, use a fighter brand in affected tiers, and watch the competitor's share gains and capacity data to decide further steps.", c: ["Understand the competitor's motive and sustainability", "Break-even volume gain needed to justify matching", "Targeted response: fighter brand and dealer incentives", "Avoid price war with an equally capable rival"], k: ["Matching a price cut requires a large volume gain to break even", "The motive of the competitor shapes the response"], m: ["Matching price automatically", "Ignoring the use of a fighter brand or segmentation"] },
  { t: "Platform: marketplace for private tutors", p: "A start-up wants to build a marketplace connecting private tutors with students in one large city. It has funding for 18 months. How should it solve the chicken-and-egg problem and monetise?", d: 2, tp: "case-strategy", i: "Two-sided marketplaces need liquidity: enough supply to satisfy demand and enough demand to retain supply. Strategy: focus on a narrow niche to reach density (for example exam preparation in maths for one age group in a few districts), then expand. Seed the harder side first; here it is typically supply, since tutors with reviews and availability make the platform attractive, and students search when they have a need. Tactics: recruit tutors with free listing and tools such as scheduling and payments, curate quality, offer guarantees of first-lesson satisfaction, and use targeted student acquisition around exam seasons. Monetisation: take rate on lessons (10 to 20 percent), subscriptions for tutors for premium visibility, or fees for students; watch disintermediation, where parties meet on the platform and then arrange payments off it, so add value to keep transactions on-platform (payments, insurance, reviews, scheduling, background checks). Metrics: time to first match, repeat booking rate, supply utilisation, and take rate net of acquisition cost. Judgments: expansion only after liquidity is achieved, and unit economics must pay back customer acquisition cost within the funded runway.", c: ["Chicken-and-egg and liquidity concept", "Niche focus and seeding the hard side", "Monetisation: take rate, subscriptions", "Disintermediation risk and key metrics"], k: ["Density in a niche beats thin coverage everywhere", "Retention and repeat bookings determine marketplace health"], m: ["Launching broadly across subjects and areas at once", "Ignoring leakage when users transact off-platform"] },
  { t: "Platform: take rate in food delivery", p: "A food-delivery platform charges restaurants a 28 percent commission. Restaurant owners complain, and a regulator is considering a cap at 15 percent. The platform's contribution margin per order is about 4 percent of order value. How should the platform think about its response?", d: 3, tp: "case-strategy", i: "Understand order economics before taking positions. On a 30 dollar order the platform earns 8.4 dollars commission but pays courier cost, payment fees, promotions, support and tech, leaving about 1.2 dollars (4 percent). A cap at 15 percent would cut revenue per order by 13 points, far above the margin, so the model would be loss-making unless offset. Levers: charge customers higher delivery or service fees; unbundle the service so restaurants can choose delivery by the platform versus self-delivery with a lower commission (a menu of tiers such as marketplace-only at 10 to 15 percent and full-service logistics at 25 to 30 percent); improve courier efficiency through batching; add advertising revenue from restaurants for visibility; and reduce promotions. Competitive and strategic considerations: restaurants multi-home and consumers compare; the platform's power depends on demand scale, but over-extraction can push restaurants to direct ordering and cause long-term loss. Engage with the regulator by demonstrating the cost of delivery services and proposing tiered pricing. Recommendation: introduce unbundled pricing, shift revenue to consumer fees and ads, and prepare for cap scenarios with cost reductions.", c: ["Order-level economics showing a thin margin", "Unbundled tiered pricing and multi-sided revenue shift", "Impact of a commission cap", "Restaurant multi-homing and regulator engagement"], k: ["Both sides' price sensitivity determines who pays", "Unbundling aligns price with services provided"], m: ["Assuming commission can simply be absorbed", "Ignoring consumer-side pricing and advertising revenue"] },
  { t: "Public sector: boosting city bus ridership", p: "A mid-sized city's bus ridership has fallen 20 percent in five years, even though the population has grown. The transit authority asks how to win riders back within a fixed budget. What do you recommend?", d: 1, tp: "case-strategy", i: "Define the objective (ridership, equity, emissions, or farebox revenue) and diagnose why people left. Possible causes: slow and unreliable service (congestion and infrequent buses), poor network coverage relative to where people live and work, fares, comfort and safety, competition from cars and ride-hailing, and changes in work patterns such as remote work. Analyses: ridership by route and time, survey of lapsed riders, journey time of bus versus car, on-time performance, and mapping of population and jobs against routes. Options within a fixed budget: redesign the network around a few high-frequency corridors (frequency is usually the biggest driver of use), add bus lanes and signal priority (improves speed cheaply compared with new vehicles), simplify fares and enable contactless payment, and improve real-time information. Trade-offs: concentrating frequency on main corridors may reduce coverage in low-density areas, so weigh equity goals. Recommendation: run a pilot corridor with higher frequency and priority lanes, measure ridership response, then scale and fund through reallocation from low-use routes.", c: ["Clarify objective and diagnose causes", "Frequency, speed and coverage as key service drivers", "Low-cost interventions such as bus lanes and signal priority", "Pilot corridor and trade-off with equity"], k: ["Frequency and reliability drive ridership more than fares", "Public objectives may conflict, so state priorities"], m: ["Cutting fares as the sole fix", "Ignoring why lapsed riders left"] },
  { t: "Non-profit: food bank facing donation decline", p: "A food bank serving a large region has seen donations of food fall 25 percent while demand has risen 30 percent. It has a small budget and many volunteers. How should it respond?", d: 2, tp: "case-strategy", i: "Close the gap by increasing supply, improving efficiency and managing demand allocation. Supply: diversify sources beyond retail donations, such as farm gleaning and surplus produce, manufacturers' overruns, government programs and bulk purchasing with cash donations (a dollar buys several meals when purchased at wholesale). Increase donor retention and corporate partnerships through clear impact reporting and ask programs such as workplace drives. Efficiency: reduce waste and spoilage through better storage, rotation, and logistics (consolidated pickups), use volunteers where skills fit, and pool distribution with partners. Demand management: prioritise those most in need through targeting rules and partner agencies, offer client choice to reduce waste, and connect clients with other support services. Analyses: sources of food and money by type, cost per meal, spoilage rate and demand by area. Judgments: avoid compromising nutrition and dignity, and recognise that a persistent structural gap needs advocacy or funding from government. Recommendation: pursue cash fundraising and agricultural surplus partnerships as the quickest levers, implement waste reduction, and set targets for cost per meal and meals distributed.", c: ["Diversify supply: farms, manufacturers, government, purchasing", "Efficiency: spoilage, logistics, volunteer deployment", "Demand targeting and partner agencies", "Metrics such as cost per meal and spoilage"], k: ["Cash donations can purchase more food at wholesale than in-kind items", "Impact reporting increases donor retention"], m: ["Assuming more volunteers alone close the gap", "Ignoring spoilage and logistics"] },
  { t: "Public sector: raising tax collection", p: "A national tax authority collects only 70 percent of the taxes legally due from small and medium businesses. The finance ministry wants to raise compliance by five points over three years without a large budget increase. What would you recommend?", d: 3, tp: "case-strategy", i: "Decompose the tax gap: businesses not registered, registered but under-reporting income, filing late, and filing correctly but not paying. Different causes need different tools. Segment businesses by size, sector and behaviour, and use data analytics to target audits at highest expected recovery rather than random checks. Levers: simplification (pre-filled returns, simplified regimes for micro businesses, easy digital payment) to lower the cost of compliance; deterrence through risk-based audits, matching third-party data (bank, payment processor and invoice data), and e-invoicing which makes under-reporting harder; nudges such as reminder letters, which have strong evidence of cheap effect; and enforcement against persistent non-payers. Judgments: balance enforcement and trust, as heavy-handedness can push businesses into the informal economy; consider ratio of audit cost to recovery, and fairness across sectors. Measure progress via voluntary compliance rate and cost per dollar collected. Recommendation: lead with e-invoicing and data matching plus nudge campaigns (low cost, large scale), reserve audits for high-risk cases, and simplify regimes for the smallest firms.", c: ["Decompose the tax gap by cause", "Segmentation and risk-based audit targeting", "Simplification, e-invoicing and nudges", "Balance deterrence with trust and cost-effectiveness"], k: ["Different non-compliance causes need different tools", "Data matching can scale enforcement cheaply"], m: ["Assuming more audits are the only lever", "Ignoring compliance costs for small firms"] },
  { t: "Profitability: farm-equipment dealer", p: "A dealer of tractors and farm machinery has seen revenue fall 10 percent and operating profit fall 40 percent. Where would you look and what would you recommend?", d: 1, tp: "case-strategy", i: "Operating leverage makes profit fall faster than revenue when costs are fixed. Dealer income streams: new machine sales (low margin, 5 to 10 percent), used machine sales, parts (high margin, often 30 percent or more), and service labour. Costs: staff, facilities, floor-plan financing interest on inventory, depreciation and write-downs on unsold machines. Approach: split the revenue decline by stream and the profit decline by margin; check floor-plan costs, as unsold machines increase interest and discounting. Likely hypothesis: new machine sales fell with farm incomes, forcing discounts on stock, while fixed costs of staff and sites remained. Levers: align inventory to demand and reduce stock holding, push higher-margin parts and service (an annuity less sensitive to the cycle, for example service contracts and seasonal maintenance packages), improve used machine trade-ins, and adjust fixed costs such as consolidating branches or reducing staff through attrition. Recognise the cyclical nature, so avoid cutting service capacity that supports long-term loyalty. Recommend actions with expected profit effect.", c: ["Revenue streams and margins: new, used, parts, service", "Operating leverage and fixed costs", "Inventory and floor-plan financing", "Shift to parts and service, adjust fixed costs"], k: ["Parts and service stabilise profit through the cycle", "Inventory discipline matters in downturns"], m: ["Assuming new machine sales are the main profit source", "Cutting service capacity that supports loyalty"] },
  { t: "Capacity expansion: new factory decision", p: "A producer of battery packs for e-bikes runs its single plant at 95 percent utilisation with demand growing 20 percent a year. A second plant costs 80 million dollars and takes two years to build. Should it build, and how should it decide?", d: 3, tp: "case-strategy", i: "Frame as an investment decision under demand uncertainty. Estimate demand: market growth, the firm's share, customer contracts, and the risk that growth slows or competitors such as Asian suppliers add capacity and cut prices. Economics: unit contribution margin times incremental volume minus fixed costs gives annual cash flow; compute net present value and payback over a realistic horizon, using base, low and high demand scenarios. Example: if the plant adds 500,000 packs a year at 40 dollars contribution each, that is 20 million dollars annually at full use, a 4-year simple payback but with ramp-up, probably 5 to 6 years. Alternatives: debottleneck the existing plant (add shifts, automation), outsource to a contract manufacturer, build in stages or modular capacity, or build in a lower-cost location. Strategic factors: lost sales from capacity shortage today, customer commitments, supply security, and the option value of building later. Risks: technology change in cell chemistry and price pressure. Recommendation: pursue cheap debottlenecking now, secure anchor-customer contracts, and build in phases tied to contracted volume, thus limiting the downside if growth slows.", c: ["Demand scenarios and market risks", "Incremental economics: contribution, NPV, payback", "Alternatives: debottlenecking, outsourcing, phased build", "Anchor contracts and option value of waiting"], k: ["Capacity decisions should be tested across demand scenarios", "Phasing preserves flexibility under uncertainty"], m: ["Building because utilisation is high without testing demand durability", "Ignoring cheaper capacity alternatives"] },
  { t: "Divestiture: conglomerate considering selling a division", p: "A diversified industrial group has five divisions. The smallest, a specialty-valve business with 10 percent of group revenue, earns lower returns than the others. A hedge fund investor argues the group should sell it. Evaluate.", d: 3, tp: "case-strategy", i: "Test whether the group is the best owner and whether value is created by selling. First measure the division on return on capital versus its cost of capital (not just versus other divisions) and on growth prospects: a division below the group average may still earn above its cost of capital and create value. Value: what is the division worth held and improved (margin fixes, pricing) versus the price a buyer would pay, including a buyer's synergies; strategic buyers may pay more than the group's own valuation. Fit: shared technologies, customers, or channels, and what the group would lose in diversification and cross-selling; dis-synergies from separating shared plants, IT and overheads (stranded costs). Consider alternatives: spin-off, minority stake sale, or improve first. Taxes and timing: capital gains, the cycle in the valve market. Use of proceeds: if the group has attractive reinvestment or buy-back options, selling is more attractive; if not, the cash might sit idle. Recommendation: sell only if the bid exceeds the value in the group's hands net of stranded costs and tax, otherwise fix and revisit; avoid selling simply because of activist pressure.", c: ["Return on capital versus cost of capital", "Best-owner logic and buyer synergies", "Stranded costs, taxes and alternatives like spin-off", "Use of proceeds and decision rule"], k: ["Underperformance relative to peers differs from value destruction", "Compare sale price with hold value net of separation costs"], m: ["Selling because returns are below the group average", "Ignoring stranded costs and taxes"] },
  { t: "Market sizing within a case: EV charging demand in a city", p: "A charging network operator asks how many public fast-charging points a city of 2 million people will need in five years. Show how you would size this, state your assumptions and point out the key judgments.", d: 1, tp: "case-strategy", i: "Use a bottom-up demand estimate. Population of 2 million with about 2.5 people per household gives roughly 800,000 households, and perhaps 0.9 cars per household gives about 720,000 cars. Assume electric vehicles reach 20 percent in five years, so about 145,000 EVs. Split by home charging: perhaps 60 percent have private charging, leaving about 58,000 EVs reliant on public charging. Assume each public-reliant EV charges about 2 times a week, with 20 percent of those sessions on fast chargers (the rest slow), giving roughly 23,000 fast sessions a week, or 3,300 a day. Each fast charger delivers perhaps 12 sessions a day at 40 percent utilisation (about 30 minutes a session), so about 275 chargers are needed, rounded to 250 to 350 with peak buffer of 1.5x for peaks to maybe 400. Key judgments: EV adoption rate, share with home charging (apartment-heavy cities need more public chargers), session length, and utilisation target. Sanity-check against ratios such as ten EVs per public charger. Sensitivity: each 5 point change in adoption shifts the need by about 25 percent.", c: ["Bottom-up chain: households, cars, EV share", "Home charging share to find public-reliant EVs", "Sessions per week and charger throughput", "Sensitivities and sanity check"], k: ["State assumptions explicitly and round for easy mental math", "Sanity-check against ratios from other markets"], m: ["Using population directly without conversion to cars and EVs", "Ignoring home charging availability"] },
  { t: "Joint venture: automaker partnering locally in India", p: "A European automaker with no presence in India is weighing a joint venture with a large local conglomerate versus building a wholly owned plant. What should it consider and what would you recommend?", d: 3, tp: "case-strategy", i: "Compare control, capital, speed, capability and risk. Market: India's passenger car market is price-sensitive, dominated by compact cars and SUVs at low price points, with a large local supply chain and strong incumbent brands. A joint venture contributes local knowledge, access to dealers and suppliers, regulatory relationships, shared capital and political cover, which speeds entry and reduces risk. The costs: shared profits, conflicts on strategy and brand, intellectual property leakage risk, governance deadlocks and exit complexity. A wholly owned plant gives control and full profit capture but needs more capital, longer learning and exposure to local-content and tariff rules. Key judgments: how much local cost engineering the product needs (a Europe-designed car is likely too expensive, so local partner capability in design for cost matters), the partner's alignment and track record, whether import tariffs make local production necessary. Structure to mitigate: clear IP ring-fencing, decision rights, deadlock resolution, buy-out options, and phased commitment. Recommendation: a joint venture or partnership for first-phase entry with an option to raise stake, provided the partner has complementary strengths and protective terms.", c: ["Control, capital, speed and capability trade-offs", "Local market conditions: price points, supply chain, tariffs", "Joint venture risks: IP, governance, exit", "Structural protections and phased commitment"], k: ["Local-cost product engineering is a core capability gap", "Governance terms matter as much as the choice itself"], m: ["Seeing joint venture only as capital sharing", "Ignoring IP leakage and deadlock risks"] },
  { t: "Digital transformation: retail bank branch network", p: "A retail bank has 300 branches. Digital transactions are now 80 percent of all customer interactions, but branches account for 45 percent of operating cost. The CEO wants a transformation plan. What would you recommend?", d: 2, tp: "case-strategy", i: "Redesign the channel model around customer needs and unit economics. Segment branch usage: simple transactions (cash, balances) shift to digital or ATMs, while advice for mortgages, small-business and wealth, plus vulnerable or older customers, still value human contact. Analyse each branch: footfall, transactions, sales, profit contribution, local competition and lease terms. Options: close or merge low-value branches, convert others to smaller advice-focused formats, create hubs with staff available by video, partner for cash services (post offices or retailers), and invest in digital capability to move servicing online. Compare cost savings with revenue risk: closing branches may lose customers, particularly in rural areas, and reputational and regulatory considerations matter. Phase it: start with branches close to others, pilot new format, measure attrition and satisfaction. Also consider redeploying staff to advisory roles and retraining. Quantify: closing 90 branches might save a few hundred million depending on cost, but one-off costs of severance and lease exits matter. Recommendation: phased rationalisation of overlapping branches, transition to advice-led formats, and heavy digital investment, with attrition monitored.", c: ["Segment interactions by type and customer", "Branch-level profitability and overlap analysis", "Format options: hubs, advice branches, partnerships", "Phasing, one-off costs and attrition monitoring"], k: ["Branch closures risk customer loss and need careful sequencing", "Advice work still depends on human interaction"], m: ["Closing branches uniformly based on cost alone", "Ignoring one-off exit costs and customer attrition"] },
  { t: "Supply chain: fashion retailer with excess inventory", p: "A fashion retailer ends each season with 25 percent of stock unsold and has to mark it down heavily, hurting margins. At the same time popular items often run out. How would you fix the inventory problem?", d: 2, tp: "case-strategy", i: "This shows a mismatch between what is bought and what sells, caused by long lead times and forecast error. Diagnose: forecast accuracy by category, commitment timing (how much is ordered months before the season), sell-through by item, markdown timing, and stock-outs. Levers: (1) Better demand forecasting using sales data, trends and store-level information. (2) Shorter lead times and flexibility: commit only part of the quantity early (for example 50 to 60 percent) and reserve the rest for in-season reorders based on early sales, using nearer-shore suppliers for fast-moving items even at higher unit cost. (3) Allocation: allocate stock across stores and online dynamically and transfer between stores. (4) Pricing: earlier and smaller markdowns instead of deep late ones, plus a clearance channel (outlets, off-price retailers, online marketplaces). (5) Assortment: reduce the number of styles to concentrate buying depth on winners. Trade-off: unit cost versus markdown and lost sales savings, so compute total cost. Recommendation: test an in-season reorder model for a fast-fashion capsule to quantify reductions in markdown and stockouts, and then scale.", c: ["Diagnose forecast error and commitment timing", "Postponed commitment and in-season reorders", "Store allocation and pricing or markdown strategy", "Total cost trade-off of nearshoring"], k: ["Fewer early commitments reduce both overstock and stockouts", "Compare unit cost premium against markdown savings"], m: ["Assuming the solution is to buy fewer items overall", "Evaluating suppliers only on unit cost"] },
  { t: "Loyalty program for a grocery chain", p: "A regional grocery chain with 80 stores is considering launching a loyalty card program. The CFO is skeptical about the cost. Advise on whether and how to do it.", d: 1, tp: "case-strategy", i: "A loyalty program is worthwhile only if it changes behaviour or generates data that creates value exceeding its cost. Benefits: increased share of wallet and visit frequency from members, retention against competitors, data for personalised offers, better range and promotion decisions, and revenue from supplier-funded promotions and media. Costs: discounts or points given to customers who would have bought anyway (the largest cost), technology and data platform, marketing and administration. Test economics: incremental margin from behaviour change versus the cost of rewards plus operations; for example, if members increase spending by 5 percent but receive a 2 percent reward on all their spending, the net effect depends on the margin on incremental sales. Design: tiered personalised rewards rather than universal discounts, funding by suppliers, and use of data. Risks: copycat programs by competitors, privacy compliance. Recommendation: run a pilot in 10 stores with a control group, measure incremental sales and margin, and decide after six months. Include customer data privacy governance.", c: ["Benefits: frequency, share of wallet, data", "Costs: rewards given on baseline purchases, technology", "Incremental margin versus cost test", "Pilot with control group and supplier funding"], k: ["Rewarding purchases that would have happened anyway is the key cost", "A control group isolates the true uplift"], m: ["Assuming loyalty cards always raise sales", "Giving broad uniform discounts"] },
  { t: "Sustainability: steel producer deciding on decarbonisation", p: "An integrated steel producer with blast furnaces must decide whether to invest 1.5 billion dollars in hydrogen-based direct reduction to cut emissions by 90 percent. Customers and regulators are pushing but the green steel premium is uncertain. How should the board decide?", d: 3, tp: "case-strategy", i: "Treat it as a large irreversible investment under policy, price and technology uncertainty. Demand and premium: which customers (automakers, appliance makers) will contract at a green premium and for what volume; the outlook for carbon pricing and border carbon adjustments that make carbon-intensive steel more expensive. Costs: capital, availability and price of green hydrogen and renewable electricity (the dominant operating cost), ore quality needs, and cost per tonne versus conventional steel with a carbon price. Compare scenarios: if carbon prices reach 100 dollars per tonne and a blast furnace emits about 2 tonnes of carbon dioxide per tonne of steel, the cost penalty is 200 dollars per tonne, so low-carbon production could pay back. Also include risks of stranded assets for blast furnaces approaching relining, subsidies and public funding, and first-mover versus follower options. Alternatives: phased conversion, gas-based direct reduction as a transition fuel, partnerships for hydrogen supply, or scrap-based electric arc furnaces. Recommendation: stage the investment, sign offtake contracts and power agreements first, and align with the furnace relining schedule to avoid stranding.", c: ["Customer demand, green premium and carbon price scenarios", "Operating cost dominated by energy and hydrogen supply", "Alternatives and phasing, including electric arc furnaces", "Timing against furnace relining and stranded asset risk"], k: ["Policy and energy prices drive the economics more than technology", "Offtake and power agreements de-risk the investment"], m: ["Evaluating purely on today's cost without carbon price scenarios", "Treating it as all-or-nothing"] },
  { t: "Make versus buy: outsourcing IT support", p: "A 3,000-employee professional-services firm is considering outsourcing its internal IT helpdesk and infrastructure support to a vendor promising 20 percent savings. What do you consider?", d: 1, tp: "case-strategy", i: "Compare total cost and strategic risk, not just the quoted price. Costs: current fully loaded internal cost; vendor price over several years including transition costs, governance and contract management staff, exit costs and change fees, which often erode headline savings. Quality: service level agreements, response times, user satisfaction and knowledge of the firm's systems; risk of declining service after transition. Strategic factors: is IT support a core differentiator (generally no for helpdesk, but yes for client-facing platforms), data security and confidentiality for client information, regulatory compliance and the ability to bring services back. Alternatives: partial outsourcing of commodity tasks, shared services, automation and self-service tools. Risks: vendor lock-in, loss of institutional knowledge, and staff morale. Recommendation: outsource only well-defined commodity tasks with strict service levels, security audits and penalty clauses, and verify savings through a business case that includes full transition and governance costs. Pilot with a single function first.", c: ["Total cost including transition and governance", "Service quality and SLAs", "Core versus non-core activity and security", "Alternatives, lock-in and exit"], k: ["Headline savings are often eroded by hidden costs", "Outsource commodity activities and keep critical capabilities"], m: ["Choosing the lowest quote without total cost view", "Ignoring confidentiality and lock-in risk"] },
  { t: "Break-even and payback: opening a new warehouse", p: "An e-commerce retailer is considering opening a regional warehouse costing 12 million dollars upfront and 3 million dollars a year in fixed operating costs. It would save 4 dollars per order in shipping on 1.5 million orders a year. Does it pay back?", d: 2, tp: "case-strategy", i: "Compute annual net benefit: shipping savings of 4 dollars times 1.5 million orders gives 6 million dollars a year, less 3 million of fixed costs equals 3 million net. Simple payback is 12 / 3 = 4 years. The break-even order volume is fixed cost divided by saving per order: 3 million / 4 = 750,000 orders a year, so the warehouse is profitable above half the expected volume, which gives a margin of safety. Then test beyond the simple calculation: discount the cash flows (at 10 percent, a 3 million annuity over ten years is worth about 18.4 million, above the 12 million investment, for NPV of about 6 million), include ramp-up time and variable handling costs at the new site, and check whether faster delivery raises conversion and orders. Consider risks: order volume lower than forecast, mix of bulky items, inventory duplication across warehouses increasing stock holding, and lease terms. Alternatives: use a third-party logistics provider with no upfront cost. Recommendation: proceed if forecast volumes are robust, with sensitivity and compare to outsourcing.", c: ["Net annual benefit: savings minus fixed costs", "Payback and break-even volume calculation", "NPV and sensitivity to volume", "Alternatives such as third-party logistics and extra inventory costs"], k: ["Break-even volume shows how much forecast risk the project can absorb", "Include inventory duplication and ramp-up in the full economics"], m: ["Using payback alone without discounting or risk", "Forgetting variable handling costs"] },
  { t: "Public sector: reducing prison reoffending", p: "A state corrections department finds that 45 percent of released prisoners reoffend within three years, costing the state about 40,000 dollars per prisoner per year in incarceration. The governor asks for a programme to cut reoffending by a third. How would you approach it?", d: 3, tp: "case-strategy", i: "Define the target and cost-benefit logic: cutting reoffending from 45 to 30 percent avoids returning many people to prison, each a cost of tens of thousands per year plus social costs, so the programme budget can be justified by avoided costs. Diagnose drivers by group: employment, housing, substance use and mental health, family ties and age and offence type; analyse which factors most strongly predict reoffending and where interventions have evidence (education and vocational training, supported housing, treatment programmes, and post-release supervision). Segment by risk: concentrate intensive programmes on medium- and high-risk individuals since low-risk people do little better with heavy intervention. Design: begin preparation inside prison, link release to guaranteed accommodation and job placement, and use outcome-based funding with providers. Evaluate with a randomised or matched comparison group to avoid fooling ourselves, and account for selection bias. Judgments: balance budget, public safety and political acceptability; cost per avoided reoffence and payback in years. Recommendation: launch a pilot in two regions focused on housing and employment support for medium- to high-risk releasees, measured against a control group.", c: ["Cost-benefit of avoided incarceration", "Diagnose drivers and segment by risk", "Evidence-based interventions: housing, employment, treatment", "Evaluate with control groups and outcome-based funding"], k: ["Target resources on medium and high risk groups", "Rigorous evaluation avoids selection bias"], m: ["Applying one programme to all prisoners equally", "Judging success without a comparison group"] },
  { t: "Fixing underperforming stores in a restaurant chain", p: "A casual-dining chain has 120 restaurants. The bottom 25 lose money, the middle average a 5 percent margin and the top 30 earn 15 percent. The CEO asks whether to close the bottom 25. How would you decide?", d: 2, tp: "case-strategy", i: "Treat each restaurant individually and test closure against the alternative of fixing it. First, look at four-wall contribution (revenue minus restaurant-level costs) rather than margin after allocated overhead: if a store loses money after overhead but covers its own costs, closing it loses the contribution and the allocated overhead remains, harming group profit. Then investigate causes: poor location or declining area, local competition, weak management, high rent, or operational issues such as service and quality; compare to similar stores. Options per store: fix (new manager, menu or local marketing), reformat (smaller, delivery-focused), renegotiate rent, relocate, or close. Evaluate lease exit costs, severance, and impact on brand and delivery coverage. Estimate the cost and probability of turnaround versus closure savings; use a decision rule such as closing where four-wall contribution is negative with a poor outlook and lease exit is affordable. Recommendation: triage the 25 by cause, run a 6-month turnaround on fixable stores, close those with structural problems, and renegotiate leases using the closure threat.", c: ["Four-wall contribution versus allocated overhead", "Diagnose causes by store", "Options: fix, reformat, renegotiate, relocate, close", "Lease exit costs and decision rule"], k: ["Allocated overhead does not disappear when a store closes", "Triage by cause rather than treat the bottom group uniformly"], m: ["Closing all loss-making stores by default", "Using margin after allocated overhead as the criterion"] },
];
